import type { Contact } from "./types.ts";

/** Combines two records of the same person: the incoming record wins unless its field is empty. */
export function mergeContact(current: Contact, incoming: Contact): Contact {
  return {
    ...current,
    name: incoming.name !== "" ? incoming.name : current.name,
    phone: incoming.phone !== "" ? incoming.phone : current.phone,
    tags: [...new Set([...current.tags, ...incoming.tags])],
    updatedAt: Math.max(current.updatedAt, incoming.updatedAt),
  };
}
/** The form of an email address that is compared when looking for duplicate contacts. */
export function normalizeEmail(email: string): string {
  return email.trim().toLowerCase();
}
export interface Contact {
  id: string;
  email: string;
  name: string;
  phone: string;
  tags: string[];
  updatedAt: number;
}
import { parseContactsCsv, toContactsCsv } from "./csv.ts";
import { mergeContacts } from "./import.ts";

/** Merges an uploaded CSV into the stored address book and returns the new CSV. */
export function importCsv(storedCsv: string, uploadedCsv: string): string {
  const merged = mergeContacts(parseContactsCsv(storedCsv), parseContactsCsv(uploadedCsv));
  return toContactsCsv(merged);
}
import assert from "node:assert/strict";
import { test } from "node:test";
import { mergeContacts } from "../src/import.ts";
import type { Contact } from "../src/types.ts";

function contact(id: string, email: string, overrides: Partial<Contact> = {}): Contact {
  return { id, email, name: `Name ${id}`, phone: "", tags: [], updatedAt: 1, ...overrides };
}

test("new contacts are appended in arrival order", () => {
  const result = mergeContacts([contact("1", "a@x.io")], [contact("2", "b@x.io"), contact("3", "c@x.io")]);
  assert.deepEqual(
    result.map((c) => c.id),
    ["1", "2", "3"],
  );
});

test("a contact with a known email is merged into the existing entry", () => {
  const result = mergeContacts([contact("1", "a@x.io", { tags: ["vip"] })], [contact("2", "a@x.io", { tags: ["beta"] })]);
  assert.equal(result.length, 1);
  assert.equal(result[0].id, "1");
  assert.deepEqual(result[0].tags, ["vip", "beta"]);
});

test("emails are compared without case and surrounding whitespace", () => {
  const result = mergeContacts([contact("1", "Ada@X.io")], [contact("2", " ada@x.IO ")]);
  assert.equal(result.length, 1);
});

test("duplicates inside the incoming list are merged with each other", () => {
  const result = mergeContacts([], [contact("1", "a@x.io", { phone: "111" }), contact("2", "a@x.io", { name: "" })]);
  assert.equal(result.length, 1);
  assert.equal(result[0].phone, "111");
});
